        with open(path) as f:
            data = json.load(f)
        for m in data:
            if 'IRT' in m.get('method',''):
                print(f'{ver} IRT: scores={m.get(\"calibrated_scores\",\"N/A\")[:8]}...')
                break
    else:
        print(f'{ver}: no evaluation.json')
